mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p;
  q.z += time * 1.0;
  vec2 id = floor(q.xz / 1.0);
  q.xz = mod(q.xz, 1.0) - 0.5;
  float h = 1.0 + 0.6 * sin(id.x * 1.5 + id.y * 2.0 + time * 2.0);
  float spire = length(q.xz) - 0.08 * (1.0 - (p.y + 1.0) / (h + 1.0));
  spire = max(spire, -p.y - 1.0);
  spire = max(spire, p.y - h);
  return spire;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 2.5, -3.5);
  vec3 rd = normalize(vec3(p, 1.5));
  rd.yz = rot(-0.6) * rd.yz;
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 12.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.01, 0.04, 0.03);
  if (t < 12.0) {
    vec3 pos = ro + rd * t;
    float beacon = step(0.8, fract(pos.y * 3.0));
    float fog = 1.0 / (1.0 + t * t * 0.04);
    col = (vec3(0.05, 0.1, 0.08) + beacon * vec3(0.1, 1.0, 0.5) * 2.0) * fog;
  }
  ret = col;
}
